(()=>{'use strict';const button=document.getElementById('copyDownloaderCode'),input=document.getElementById('downloaderCode'),status=document.getElementById('downloaderCopyStatus');if(!button||!input)return;button.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(input.value);status.textContent='Código copiado. Digite 4049585 no Downloader.';}catch{input.focus();input.select();status.textContent='Selecione e copie o código 4049585.';}});})();
